from django.db import migrations, models


def deduire_regimes(apps, schema_editor):
    """Chaque bien existant reçoit le régime qui correspond à sa comptabilité et au type de son propriétaire,
    marqué « à vérifier » jusqu'à ce que sa fiche soit enregistrée."""
    Bien = apps.get_model("patrimoine", "Bien")
    for bien in Bien.objects.select_related("proprietaire"):
        type_proprio = bien.proprietaire.type
        societe = type_proprio != "nom_propre"
        if type_proprio == "sci_is":
            regime = "societe_is"
        elif bien.comptabilite == "foncier":
            regime = "sci_ir" if societe else "nu"
        elif bien.comptabilite == "lmnp":
            regime = "societe_ir" if societe else "lmnp"
        elif bien.comptabilite == "societe":
            regime = "societe_ir"
        else:
            regime = "non_loue"
        Bien.objects.filter(pk=bien.pk).update(regime_fiscal=regime, option_fiscale="reel", regime_a_verifier=True)


